from __future__ import annotations


def android_client(*, base_url: str = 'https://148ailabs.com') -> dict[str, str]:
    app_id='com.one48ai.mobile'; pkg=app_id.replace('.','/')
    return {
        'settings.gradle.kts':'pluginManagement { repositories { google(); mavenCentral(); gradlePluginPortal() } }\ndependencyResolutionManagement { repositoriesMode.set(RepositoriesMode.FAIL_ON_PROJECT_REPOS); repositories { google(); mavenCentral() } }\nrootProject.name="148AI"\ninclude(":app")\n',
        'build.gradle.kts':'plugins { id("com.android.application") version "8.7.3" apply false }\n',
        'app/build.gradle.kts':f'''plugins {{ id("com.android.application") }}\nandroid {{ namespace="{app_id}"; compileSdk=35\n defaultConfig {{ applicationId="{app_id}"; minSdk=26; targetSdk=35; versionCode=1; versionName="1.0" }}\n signingConfigs {{ create("release") {{ val ks=System.getenv("ONE48AI_ANDROID_KEYSTORE"); if (ks != null) storeFile=file(ks); storePassword=System.getenv("ONE48AI_ANDROID_STORE_PASSWORD"); keyAlias=System.getenv("ONE48AI_ANDROID_KEY_ALIAS"); keyPassword=System.getenv("ONE48AI_ANDROID_KEY_PASSWORD") }} }}\n buildTypes {{ release {{ signingConfig=signingConfigs.getByName("release"); isMinifyEnabled=false }} }} }}\n''',
        'app/src/main/AndroidManifest.xml':'<manifest xmlns:android="http://schemas.android.com/apk/res/android"><uses-permission android:name="android.permission.INTERNET"/><uses-permission android:name="android.permission.ACCESS_FINE_LOCATION"/><application android:usesCleartextTraffic="false" android:label="148AI"><activity android:name=".MainActivity" android:exported="true"><intent-filter><action android:name="android.intent.action.MAIN"/><category android:name="android.intent.category.LAUNCHER"/></intent-filter></activity></application></manifest>',
        f'app/src/main/java/{pkg}/MainActivity.java':f'''package {app_id};\nimport android.Manifest; import android.app.Activity; import android.os.Bundle; import android.webkit.*; import android.content.pm.PackageManager; import android.net.Uri;\npublic class MainActivity extends Activity {{ private WebView web; private ValueCallback<Uri[]> fileChooser; @Override public void onCreate(Bundle b) {{ super.onCreate(b); web=new WebView(this); setContentView(web); WebSettings s=web.getSettings(); s.setJavaScriptEnabled(true); s.setDomStorageEnabled(true); s.setGeolocationEnabled(true); web.setWebChromeClient(new WebChromeClient() {{ @Override public void onGeolocationPermissionsShowPrompt(String origin, GeolocationPermissions.Callback cb) {{ if(checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED) requestPermissions(new String[]{{Manifest.permission.ACCESS_FINE_LOCATION}},501); cb.invoke(origin,true,false); }} }}); web.loadUrl("{base_url}"); }} }}\n''',
        '.github/workflows/android-aab.yml':'name: 148ai-android-aab\non: [workflow_dispatch]\njobs:\n  aab:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n      - uses: actions/setup-java@v4\n        with: {distribution: temurin, java-version: "17"}\n      - uses: gradle/actions/setup-gradle@v4\n        with: {gradle-version: "8.9"}\n      - run: gradle bundleRelease\n        env:\n          ONE48AI_ANDROID_KEYSTORE: ${{ secrets.ONE48AI_ANDROID_KEYSTORE }}\n          ONE48AI_ANDROID_STORE_PASSWORD: ${{ secrets.ONE48AI_ANDROID_STORE_PASSWORD }}\n          ONE48AI_ANDROID_KEY_ALIAS: ${{ secrets.ONE48AI_ANDROID_KEY_ALIAS }}\n          ONE48AI_ANDROID_KEY_PASSWORD: ${{ secrets.ONE48AI_ANDROID_KEY_PASSWORD }}\n',
        'README.md':'# 148AI Android client\nBranded source wrapper for the 148AI web platform. A signed AAB requires external Android signing credentials.\n',
    }


def ios_client(*, base_url: str = 'https://148ailabs.com') -> dict[str, str]:
    return {
        'project.yml':'''name: One48AI\noptions:\n  bundleIdPrefix: com.one48ai\ntargets:\n  One48AI:\n    type: application\n    platform: iOS\n    deploymentTarget: "16.0"\n    sources: [Sources]\n    settings:\n      base:\n        PRODUCT_BUNDLE_IDENTIFIER: com.one48ai.mobile\n        PRODUCT_NAME: "148AI"\n''',
        'Sources/One48AI.swift':f'''import SwiftUI\nimport WebKit\n@main struct One48AI: App {{ var body: some Scene {{ WindowGroup {{ WebView(url: URL(string: "{base_url}")!) }} }} }}\nstruct WebView: UIViewRepresentable {{ let url: URL; func makeUIView(context: Context) -> WKWebView {{ let v=WKWebView(); v.load(URLRequest(url:url)); return v }}; func updateUIView(_ uiView: WKWebView, context: Context) {{}} }}\n''',
        '.github/workflows/ios-source-check.yml':'name: 148ai-ios-source-check\non: [workflow_dispatch, push]\njobs:\n  build:\n    runs-on: macos-latest\n    steps:\n      - uses: actions/checkout@v4\n      - run: brew install xcodegen\n      - run: xcodegen generate\n      - run: xcodebuild -project One48AI.xcodeproj -scheme One48AI -sdk iphonesimulator -destination "platform=iOS Simulator,name=iPhone 16" build CODE_SIGNING_ALLOWED=NO\n',
        'README.md':'# 148AI iOS client\nBranded SwiftUI/WKWebView client source. Signed IPA/TestFlight requires Apple Developer credentials and macOS/Xcode.\n',
    }
